//! Single-byte Windows code pages.
//!
//! The tables are generated by `tools/gen_codepages.py` from Unicode's
//! Microsoft mapping files in `data/codepages/` (Unicode License v3). The
//! ANSI tables come from the "WindowsBestFit" files, which also hold the
//! best-fit mappings `WideCharToMultiByte` uses unless it gets
//! `WC_NO_BEST_FIT_CHARS`. The OEM tables come from the plain "PC" files,
//! which have no best-fit data; there, only exact mappings exist.

#[rustfmt::skip]
mod tables;

/// One code page, both directions.
#[derive(Debug)]
pub struct SingleByte {
    pub number: u16,
    /// Written for characters the code page lacks (`CPINFO` DefaultChar).
    pub default_byte: u8,
    /// Read for bytes the code page does not define.
    pub default_unicode: u16,
    pub to_unicode: [u16; 256],
    pub defined: [bool; 256],
    /// Sorted by UTF-16 unit; includes best-fit mappings.
    pub from_unicode: &'static [(u16, u8)],
}

/// A process's ANSI and OEM code pages (`GetACP`, `GetOEMCP`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct CodePages {
    pub ansi: u16,
    pub oem: u16,
}

/// Windows 1252 and 437, for processes built without a host profile
/// (tests). The runner always takes the code pages from the profile.
impl Default for CodePages {
    fn default() -> Self {
        CodePages {
            ansi: 1252,
            oem: 437,
        }
    }
}

/// The table for code page `number`, if we have one.
pub fn single_byte(number: u16) -> Option<&'static SingleByte> {
    tables::ALL.iter().copied().find(|t| t.number == number)
}

/// The code pages we have tables for.
pub fn supported() -> Vec<u16> {
    tables::ALL.iter().map(|t| t.number).collect()
}

impl SingleByte {
    /// Bytes to UTF-16. With `strict`, None if a byte is undefined.
    pub fn decode(&self, bytes: &[u8], strict: bool) -> Option<Vec<u16>> {
        if strict && bytes.iter().any(|&b| !self.defined[b as usize]) {
            return None;
        }
        Some(bytes.iter().map(|&b| self.to_unicode[b as usize]).collect())
    }

    /// The byte for one UTF-16 unit. Without `best_fit`, only mappings
    /// that decode back to `unit` count.
    fn byte_for(&self, unit: u16, best_fit: bool) -> Option<u8> {
        let i = self
            .from_unicode
            .binary_search_by_key(&unit, |e| e.0)
            .ok()?;
        let byte = self.from_unicode[i].1;
        let round_trip = self.defined[byte as usize] && self.to_unicode[byte as usize] == unit;
        (best_fit || round_trip).then_some(byte)
    }

    /// UTF-16 to bytes, writing `default` for units without a mapping.
    /// Returns the bytes and whether `default` was used.
    pub fn encode(&self, units: &[u16], best_fit: bool, default: u8) -> (Vec<u8>, bool) {
        let mut used_default = false;
        let bytes = units
            .iter()
            .map(|&u| {
                self.byte_for(u, best_fit).unwrap_or_else(|| {
                    used_default = true;
                    default
                })
            })
            .collect();
        (bytes, used_default)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn windows_1252_both_ways_with_best_fit() {
        let t = single_byte(1252).unwrap();
        assert_eq!(t.default_byte, b'?');
        assert_eq!(
            t.decode(b"\x80\x81\xe9A", true).unwrap(),
            [0x20ac, 0x0081, 0x00e9, 0x41]
        );
        assert_eq!(
            t.encode(&[0x20ac, 0xe9], true, b'?'),
            (vec![0x80, 0xe9], false)
        );
        // Infinity becomes 8 by best fit, as the file's notes say.
        assert_eq!(t.encode(&[0x221e], true, b'?'), (vec![b'8'], false));
        assert_eq!(t.encode(&[0x221e], false, b'?'), (vec![b'?'], true));
        assert_eq!(t.encode(&[0x4e00], true, b'#'), (vec![b'#'], true));
    }

    #[test]
    fn oem_437_maps_exactly() {
        let t = single_byte(437).unwrap();
        assert_eq!(t.decode(b"\x82\xb0", true).unwrap(), [0x00e9, 0x2591]);
        assert_eq!(t.encode(&[0x00e9], true, b'?'), (vec![0x82], false));
        assert_eq!(t.encode(&[0x20ac], true, b'?'), (vec![b'?'], true));
        assert!(t.defined.iter().all(|&d| d));
    }

    #[test]
    fn tables_are_sorted_and_known() {
        assert_eq!(supported(), [1252, 437]);
        assert!(single_byte(932).is_none());
        for t in tables::ALL {
            assert!(t.from_unicode.windows(2).all(|w| w[0].0 < w[1].0));
            for b in 0..=255u8 {
                if t.defined[b as usize] {
                    let unit = t.to_unicode[b as usize];
                    assert_eq!(t.byte_for(unit, false), Some(b), "{} {b:#x}", t.number);
                }
            }
        }
    }
}
